    "Goed gezien, {0}. Eén foute gok, maar je hebt hem.": "ঠিক ধরেছেন, {0}। একবার ভুল আন্দাজ, তবু ধরে ফেলেছেন।",
    "In één keer goed, {0}. Probeer het de volgende keer eens zonder hint.": "প্রথম চেষ্টাতেই ঠিক, {0}। পরের বার ইঙ্গিত ছাড়া চেষ্টা করে দেখুন।",
