    " Lees de verklaring hierboven nog eens en probeer een vakje dat erbij past.": " উপরের বয়ানটা আরেকবার পড়ুন, তারপর তার সঙ্গে মেলে এমন একটি খোপ চেষ্টা করুন।",
    "Haal de verdachte weg en kijk welke vakjes die aanwijzing wél toelaat.": "সন্দেহভাজনকে সরিয়ে দেখুন, ওই সূত্র আসলে কোন কোন খোপ মেনে নেয়।",
    "Precies één persoon bevond zich in die kamer.": "ওই ঘরে ছিলেন ঠিক একজন।",
