    "Bedankt! Je bericht is verstuurd.": "ধন্যবাদ! আপনার বার্তা পাঠানো হয়েছে।",
    "Versturen lukt nu niet. Probeer het later opnieuw.": "এখন পাঠানো যাচ্ছে না। পরে আবার চেষ্টা করুন।",
